    39	    /// A settlement totals what the office reimburses for each damage the
    40	    /// incident reported.
    41	    pub fn claim(&self, damages: &[Damage]) -> Settlement {
    42	        let payout = damages.iter().map(damage_reimbursement).sum();
    43	        Settlement { payout }
    44	    }
