    47	/// A premium is rounded in the MHPCO's favor, which for money the customer
    48	/// owes the office means upwards.
    49	fn round_premium_in_mhpco_favor(premium: f64) -> i64 {
    50	    premium.ceil() as i64
    51	}
    52	
    53	/// How the MHPCO's two kinds of modifier reach the premium: policy-wide
    54	/// modifiers scale the policy base premium, while item-specific modifiers are
    55	/// measured against their own item's base premium and are added alongside, so
    56	/// a curse never surcharges the rest of the policy.
    57	fn premium_before_fee(customer: &Customer, items: &[Item], previous_quotes: usize) -> f64 {
    58	    let base = policy_base_premium(items);
    59	    base + standing_adjustment(base, customer, previous_quotes) + item_risk_surcharges(items)
    60	}
    61	
    62	pub fn quote(customer: &Customer, items: &[Item], previous_quotes: usize) -> i64 {
    63	    let premium = premium_before_fee(customer, items, previous_quotes);
    64	    round_premium_in_mhpco_favor(premium) + PROCESSING_FEE
    65	}
